components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 0 16px;
  border: 1px solid var(--ink, #161815);
  border-radius: 6px;
  background: var(--ink, #161815);
  color: var(--paper, #f2f3ee);
  cursor: pointer;
  font-family: "Archivo", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  font-size: 12.5px;
  font-weight: 680;
  letter-spacing: 0.015em;
  line-height: 1.2;
  transition: background-color 160ms ease, transform 160ms ease;
}
.ds-btn-primary:hover { background: #2e312c; }
.ds-btn-primary:active { transform: translateY(1px); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--focus, #2f6f9f); outline-offset: 3px; }
.ds-btn-primary svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.65; }

.ds-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 16px;
  border: 1px solid var(--rule-strong, #7e867d);
  border-radius: 6px;
  background: var(--surface, #fbfbf7);
  color: var(--ink, #161815);
  cursor: pointer;
  font-family: "Archivo", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  font-size: 12.5px;
  font-weight: 680;
  letter-spacing: 0.015em;
  line-height: 1.2;
  transition: background-color 160ms ease, transform 160ms ease;
}
.ds-btn-secondary:hover { background: var(--surface-muted, #e7e9e2); }
.ds-btn-secondary:active { transform: translateY(1px); }
.ds-btn-secondary:focus-visible { outline: 2px solid var(--focus, #2f6f9f); outline-offset: 3px; }

.ds-icon-button {
  display: inline-grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--ink, #161815);
  cursor: pointer;
  transition: background-color 160ms ease, transform 160ms ease;
}
.ds-icon-button:hover { background: var(--surface-muted, #e7e9e2); }
.ds-icon-button:active { transform: translateY(1px); }
.ds-icon-button:focus-visible { outline: 2px solid var(--focus, #2f6f9f); outline-offset: 3px; }
.ds-icon-button svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.65; }

.ds-mode-switch {
  position: relative;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  width: 188px;
  padding: 3px;
  border: 1px solid var(--rule, #c8ccc3);
  border-radius: 8px;
  background: var(--surface-muted, #e7e9e2);
  font-family: "Archivo", "Avenir Next", "Segoe UI", system-ui, sans-serif;
}
.ds-mode-switch__thumb {
  position: absolute;
  z-index: 0;
  top: 3px;
  bottom: 3px;
  left: 3px;
  width: calc(50% - 3px);
  border-radius: 5px;
  background: var(--ink, #161815);
  box-shadow: 0 1px 2px rgba(16, 20, 16, 0.16);
  transition: transform 220ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-mode-switch[data-active="practice"] .ds-mode-switch__thumb { transform: translateX(100%); }
.ds-mode-switch__button {
  position: relative;
  z-index: 1;
  min-height: 38px;
  padding: 0 8px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--ink-soft, #596159);
  cursor: pointer;
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}
.ds-mode-switch__button.is-active { color: var(--switch-active-ink, #f2f3ee); }
.ds-mode-switch__button:focus-visible { outline: 2px solid var(--focus, #2f6f9f); outline-offset: 1px; }

.ds-board-row {
  display: grid;
  grid-template-columns: repeat(5, 58px);
  gap: 7px;
}
.ds-tile {
  display: grid;
  place-items: center;
  aspect-ratio: 1;
  border: 2px solid var(--tile-border, #8b9388);
  border-radius: 6px;
  background: var(--surface, #fbfbf7);
  color: var(--ink, #161815);
  font-family: "Archivo", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  font-size: 22px;
  font-weight: 720;
  line-height: 1;
  text-transform: uppercase;
}
.ds-tile--correct { border-color: var(--accent, #3f7d4e); background: var(--accent, #3f7d4e); color: var(--accent-ink, #ffffff); }
.ds-tile--present { border-color: var(--present, #b8862f); background: var(--present, #b8862f); color: var(--present-ink, #181207); }
.ds-tile--absent { border-color: var(--absent, #666d66); background: var(--absent, #666d66); color: var(--absent-ink, #ffffff); }

.ds-key {
  width: 44px;
  height: 44px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: var(--key-bg, #dfe2db);
  box-shadow: 0 2px 0 var(--key-edge, #b7bcb3);
  color: var(--ink, #161815);
  cursor: pointer;
  font-family: "Archivo", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 690;
  line-height: 1;
  text-transform: uppercase;
  transition: background-color 160ms ease, box-shadow 80ms ease, transform 80ms ease;
}
.ds-key:hover { background: #d5d8d1; }
.ds-key:active { box-shadow: none; transform: translateY(2px); }
.ds-key:focus-visible { outline: 2px solid var(--focus, #2f6f9f); outline-offset: 3px; }
.ds-key--correct { background: var(--accent, #3f7d4e); box-shadow: 0 2px 0 var(--accent-edge, #2f633c); color: var(--accent-ink, #ffffff); }
.ds-key--correct:hover { background: var(--accent, #3f7d4e); filter: brightness(1.05); }
.ds-key--present { background: var(--present, #b8862f); box-shadow: 0 2px 0 var(--present-edge, #8d6620); color: var(--present-ink, #181207); }
.ds-key--absent { background: var(--absent, #666d66); box-shadow: 0 2px 0 var(--absent-edge, #4e544e); color: var(--absent-ink, #ffffff); }

.ds-receipt {
  width: min(100%, 410px);
  padding: 23px;
  border: 1px solid var(--rule-strong, #7e867d);
  border-radius: 13px;
  background: var(--surface, #fbfbf7);
  box-shadow: 0 22px 60px rgba(16, 20, 16, 0.16), 0 3px 10px rgba(16, 20, 16, 0.08);
  color: var(--ink, #161815);
  font-family: "Archivo", "Avenir Next", "Segoe UI", system-ui, sans-serif;
}
.ds-receipt__perf { border-top: 1px dashed var(--rule-strong, #7e867d); margin: 0 -23px 17px; }
.ds-receipt__perf:last-child { margin: 17px -23px 0; }
.ds-receipt__head { display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; }
.ds-receipt__title { margin: 0; font-size: 26px; font-weight: 780; letter-spacing: -0.035em; line-height: 1.08; }
.ds-receipt__close { display: inline-grid; place-items: center; width: 44px; height: 44px; border: 0; border-radius: 7px; background: transparent; color: inherit; cursor: pointer; } .ds-receipt__close svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.65; }
.ds-receipt__close:focus-visible { outline: 2px solid var(--focus, #2f6f9f); outline-offset: 3px; }
.ds-receipt__meta { margin: 8px 0 6px; color: var(--ink-faint, #686f67); font-size: 9.5px; font-weight: 650; letter-spacing: 0.11em; text-transform: uppercase; }
.ds-receipt__grid { display: grid; grid-template-columns: repeat(5, 18px); justify-content: center; gap: 4px; padding: 13px 0 4px; }
.ds-cell { width: 18px; height: 18px; border-radius: 2px; background: var(--absent, #666d66); }
.ds-cell--correct { background: var(--accent, #3f7d4e); }
.ds-cell--present { background: var(--present, #b8862f); }
.ds-receipt__note { margin: 5px 0 15px; color: var(--ink-faint, #686f67); font-size: 9.5px; font-weight: 620; letter-spacing: 0.1em; line-height: 1.5; text-align: center; text-transform: uppercase; }
.ds-receipt__actions { display: grid; grid-template-columns: 1.2fr 1fr; gap: 8px; }
.ds-receipt__primary, .ds-receipt__secondary { min-height: 44px; border-radius: 6px; cursor: pointer; font-family: inherit; font-size: 12.5px; font-weight: 680; }
.ds-receipt__primary { border: 1px solid var(--ink, #161815); background: var(--ink, #161815); color: var(--paper, #f2f3ee); }
.ds-receipt__secondary { border: 1px solid var(--rule-strong, #7e867d); background: var(--surface, #fbfbf7); color: var(--ink, #161815); }
.ds-receipt__primary:focus-visible, .ds-receipt__secondary:focus-visible { outline: 2px solid var(--focus, #2f6f9f); outline-offset: 3px; }
